.darma-loader-darma-b17-wax-seal-press { --accent: var(--loader-color, #be123c); --accent-2: var(--loader-secondary-color, #fee2e2); width: var(--loader-size, 116px); height: var(--loader-size, 116px); position: relative; }
.darma-loader-darma-b17-wax-seal-press .darma-loader-darma-b17-wax-seal-press__paper { position: absolute; left: 8%; right: 8%; bottom: 6%; height: 46%; border-radius: 3px; background: var(--accent-2); box-shadow: 0 3px 8px color-mix(in srgb, #000 22%, transparent); }
.darma-loader-darma-b17-wax-seal-press .darma-loader-darma-b17-wax-seal-press__blob { position: absolute; left: 32%; bottom: 16%; width: 36%; height: 26%; border-radius: 46% 54% 50% 44% / 52% 46% 54% 48%; background: radial-gradient(circle at 40% 34%, color-mix(in srgb, #fff 22%, var(--accent)), var(--accent)); transform: scale(0); animation: darma-loader-darma-b17-wax-seal-press-wax-spread calc(var(--loader-speed, 1s) * 2.6) cubic-bezier(.3, 1.3, .5, 1) infinite; }
.darma-loader-darma-b17-wax-seal-press .darma-loader-darma-b17-wax-seal-press__crest { position: absolute; left: 42%; bottom: 21%; width: 16%; height: 16%; border-radius: 3px; background: color-mix(in srgb, #000 26%, var(--accent)); clip-path: polygon(50% 0, 100% 30%, 82% 100%, 18% 100%, 0 30%); opacity: 0; animation: darma-loader-darma-b17-wax-seal-press-wax-crest calc(var(--loader-speed, 1s) * 2.6) ease-out infinite; }
.darma-loader-darma-b17-wax-seal-press .darma-loader-darma-b17-wax-seal-press__stamp { position: absolute; left: 34%; top: 2%; width: 32%; height: 44%; border-radius: 6px 6px 4px 4px; background: linear-gradient(#a16207, #78350f); animation: darma-loader-darma-b17-wax-seal-press-wax-press calc(var(--loader-speed, 1s) * 2.6) cubic-bezier(.5, 0, .3, 1) infinite; }
.darma-loader-darma-b17-wax-seal-press .darma-loader-darma-b17-wax-seal-press__stamp::after { content: ''; position: absolute; left: 16%; right: 16%; top: -22%; height: 30%; border-radius: 4px; background: #92400e; }
@keyframes darma-loader-darma-b17-wax-seal-press-wax-press { 0%, 18% { transform: translateY(0); } 40%, 54% { transform: translateY(74%); } 78%, 100% { transform: translateY(0); } }
@keyframes darma-loader-darma-b17-wax-seal-press-wax-spread { 0%, 22% { transform: scale(0); } 46%, 100% { transform: scale(1); } }
@keyframes darma-loader-darma-b17-wax-seal-press-wax-crest { 0%, 56% { opacity: 0; } 68%, 92% { opacity: 1; } 100% { opacity: 0; } }

